"""Agenda rendering for TTDL todo.txt records."""
from datetime import date, datetime
import re


def _todo(line):
    # Return subject, date value, and time value from a todo.txt line.
    s = line.strip()
    if not s:
        return None
    s = re.sub(r"^x\s+(?:\d{4}-\d\d-\d\d\s+)?", "", s)
    s = re.sub(r"^\([A-Z]\)\s+", "", s)
    tags = dict(re.findall(r"(?<!\S)([A-Za-z][\w-]*):([^\s]+)", s))
    return s, tags


def _date_value(value, today):
    if not value:
        return None
    if value == "today":
        return today
    if value == "tomorrow":
        return today.fromordinal(today.toordinal() + 1)
    if value == "yesterday":
        return today.fromordinal(today.toordinal() - 1)
    try:
        return date.fromisoformat(value)
    except ValueError:
        return None


def _minutes(v, fallback):
    if v is None or v == "":
        return fallback
    m = re.fullmatch(r"(\d{1,2})(\d{2})(am|pm)?", v, re.I)
    if not m:
        return None
    h, minute = int(m[1]), int(m[2])
    ap = (m[3] or "").lower()
    if minute > 59:
        return None
    if ap:
        h = h % 12 + (12 if ap == "pm" else 0)
    if h > 24 or (h == 24 and minute):
        return None
    return h * 60 + minute


def render_agenda(lines, on=None, hide_all_day=False, start=480, end=1200, slot=30):
    """Render a basic agenda. `lines` are raw records; `on` is an ISO date."""
    today = date.today()
    target = _date_value(on, today) if on else today
    if target is None:
        target = today
    timed, allday = [], []
    for n, line in enumerate(lines, 1):
        item = _todo(line)
        if not item:
            continue
        subject, tags = item
        # Exclude completed and hidden records by default.
        if re.match(r"^x\s", line.strip()) or tags.get("h"):
            continue
        if _date_value(tags.get("due"), target) != target:
            continue
        tv = tags.get("time")
        if not tv:
            allday.append((n, subject))
            continue
        bits = re.split(r"[-.]", tv, maxsplit=1)
        a = _minutes(bits[0], None)
        b = _minutes(bits[1], None) if len(bits) > 1 else None
        if a is not None and (b is None or b > start) and a < end:
            timed.append((n, subject, a, b))
    out = []
    for minute in range(start, end + 1, max(1, slot)):
        label = f"{minute // 60:02d}:{minute % 60:02d}  "
        marks = []
        for n, subject, a, b in timed:
            if a <= minute < (b if b is not None else end):
                marks.append(f"{n}.{subject}")
        out.append(label + (marks[0] if marks else ""))
    if not hide_all_day:
        if allday:
            out.extend(["", "All day:"] + [f" {n}.{s}" for n, s in allday])
    return "\n".join(out) + "\n"

