#!/usr/bin/env python3
"""A small todo.txt-compatible TTDL command line implementation."""
import datetime as dt
import os
import re
import sys

from agenda import render_agenda
from stats import run_stats, run_taglist
from timers import timer_record

ALIASES = {'l':'list','ls':'list','a':'add','d':'done','e':'edit','rm':'remove','c':'clean','arc':'clean','app':'append','prep':'prepend','lp':'listprojects','listproj':'listprojects','lc':'listcontexts','listcon':'listcontexts','lh':'listhashtags','ag':'agenda'}
COMMANDS = set('list add done undone remove clean edit append prepend postpone stats listprojects listcontexts listhashtags agenda start stop'.split())

def paths(args):
    filename=os.environ.get('TTDL_FILENAME')
    if not filename:
        filename='todo.txt'
        if os.path.exists('ttdl.toml'):
            try:
                import tomllib
                with open('ttdl.toml','rb') as f: filename=tomllib.load(f).get('global',{}).get('filename') or filename
            except Exception: pass
    if '--local' in args: filename='todo.txt'
    if os.path.isdir(filename): filename=os.path.join(filename,'todo.txt')
    return filename

def tokens(line):
    return re.findall(r'(?<!\S)([A-Za-z][\w-]*):([^\s]+)',line)

def gettag(line,key):
    vals=[v for k,v in tokens(line) if k==key]
    return vals[-1] if vals else None

def settag(line,key,value):
    pat=r'(?<!\S)'+re.escape(key)+r':[^\s]+'
    line=re.sub(pat,'',line).strip()
    return (line+' ' if line else '')+key+':'+value if value is not None else line

def done(line): return bool(re.match(r'^x(?:\s|$)',line))
def hidden(line): return bool(gettag(line,'h'))
def priority(line):
    m=re.match(r'^\(([A-Z])\)\s*',line)
    return m.group(1) if m else ''
def due(line):
    v=gettag(line,'due')
    try:return dt.date.fromisoformat(v) if v else None
    except ValueError:return None

def human_date(s):
    today=dt.date.today()
    if s=='today':return today
    if s=='tomorrow':return today+dt.timedelta(days=1)
    if s=='yesterday':return today-dt.timedelta(days=1)
    m=re.fullmatch(r'([+-]?\d+)([dwmy]?)',s or '')
    if m:
        n=int(m[1]); unit=m[2]
        return today+dt.timedelta(days=n*(7 if unit=='w' else 30 if unit=='m' else 365 if unit=='y' else 1))
    try:return dt.date.fromisoformat(s)
    except (ValueError,TypeError):return None

def match_date(value, spec, key='due'):
    if not spec:return True
    d=human_date(value) if value else None
    if spec=='none':return d is None
    if spec=='any':return d is not None
    if spec=='overdue':return d is not None and d<dt.date.today()
    if spec=='soon':return d is not None and d<=dt.date.today()+dt.timedelta(days=7)
    if '..' in spec:
        if spec.endswith('..'):spec+=''
        bits=spec.split('..')
        if len(bits)>=2:
            lo=human_date(bits[0]) if bits[0] else None; hi=human_date(bits[-1]) if bits[-1] else None
            return d is not None and (lo is None or d>=lo) and (hi is None or d<=hi)
    target=human_date(spec)
    return d is not None and target==d

def pattern_match(value,patterns):
    if not patterns:return True
    values=value or []
    for p in patterns:
        if p=='none' and not values:return True
        if p=='any' and values:return True
        if p.startswith('*') and p.endswith('*') and len(p)>2:
            if any(p[1:-1].lower() in x.lower() for x in values):return True
        elif p.startswith('*'):
            if any(x.lower().endswith(p[1:].lower()) for x in values):return True
        elif p.endswith('*'):
            if any(x.lower().startswith(p[:-1].lower()) for x in values):return True
        elif any(x.lower()==p.lower() for x in values):return True
    return False

def parse_args(argv):
    args=list(argv); cmd=None; positional=[]; opts={}; flags=set(); projects=[]; contexts=[]
    i=0
    while i<len(args):
        a=args[i]
        if a.startswith('--'):
            k,eq, v=a[2:].partition('=')
            if eq:opts[k]=v
            elif k in ('due','created','completed','threshold','pri','rec','project','context','tag','hashtag','sort','group','set-pri','set-due','set-rec','set-time','set-threshold','set-proj','set-ctx','set-tag','set-hashtag','del-proj','del-ctx','del-tag','del-hashtag','repl-proj','repl-ctx','repl-hashtag','calendar','max','width','date-format','on','time','slot','resolution','src') and i+1<len(args) and not args[i+1].startswith('-'):
                i+=1;opts[k]=args[i]
            else:flags.add(k)
        elif a.startswith('-') and a not in ('-',):
            for c in a[1:]:
                if c=='a':flags.add('all')
                elif c=='A':flags.add('only-completed')
                elif c=='t':flags.add('active')
                elif c=='e':flags.add('regex')
                elif c=='v':flags.add('verbose')
                elif c=='H':flags.add('no-headers')
                elif c=='s':
                    if i+1<len(args) and not args[i+1].startswith('-'):i+=1;opts['sort']=args[i]
                elif c=='i':flags.add('interactive')
        elif cmd is None and (a in COMMANDS or ALIASES.get(a) in COMMANDS):cmd=ALIASES.get(a,a)
        elif a.startswith('+'):projects.append(a[1:])
        elif a.startswith('@'):contexts.append(a[1:])
        else:positional.append(a)
        i+=1
    if cmd is None:cmd='list' if not positional else 'add'
    return cmd,positional,opts,flags,projects,contexts

def parse_ids(pos):
    if not pos:return None
    s=pos[0]
    if not re.fullmatch(r'[\d,-]+',s):return None
    out=set()
    for bit in s.split(','):
        if '-' in bit:
            a,b=(bit.split('-',1)+[''])[:2]
            try:out.update(range(int(a),int(b)+1))
            except ValueError:pass
        else:
            try:out.add(int(bit))
            except ValueError:pass
    return out

def render(lines, selected, flags, opts):
    full = any(re.search(r'(?<!\S)(?:\d{4}-\d\d-\d\d|due:)', line) for _,line in selected)
    header=' # D P Created    Finished   Due        Subject' if full else ' # D P Created Finished Due Subject'
    rows=[]
    for i,line in selected:
        complete=done(line); body=re.sub(r'^x\s+(?:\d{4}-\d\d-\d\d\s*)?','',line) if complete else line
        pri=priority(line); dates=re.findall(r'(?<!\S)(\d{4}-\d\d-\d\d)(?=\s|$)',line)
        created=''; finished=''
        if complete:
            if len(dates)>0:finished=dates[0]
            if len(dates)>1:created=dates[1]
        else:
            m=re.match(r'^(?:\([A-Z]\)\s+)?(\d{4}-\d\d-\d\d)\s+',line)
            if m:created=m.group(1)
        dv=gettag(line,'due') or ''
        if dv and human_date(dv):dv=human_date(dv).isoformat()
        # Standard default columns and stable widths.
        subject=body
        if complete:
            subject=re.sub(r'^x\s+(?:\d{4}-\d\d-\d\d\s+)?','',subject)
            subject=re.sub(r'^\d{4}-\d\d-\d\d\s+','',subject)
        subject=re.sub(r'^\([A-Z]\)\s*','',subject)
        subject=re.sub(r'^\d{4}-\d\d-\d\d\s+','',subject)
        if full:
            row=f"{i:2d} {'x' if complete else ' '} {pri or ' ':1s} {created:10s} {finished:10s} {dv:10s} {subject}"
        else:
            prefix=f"{i:2d} {'x' if complete else ' '} {pri or ' ':1s} "
            row=prefix+' '*max(0,29-len(prefix))+subject
        rows.append(row.rstrip())
    if 'no-headers' in flags and 'short' in flags:return '\n'.join(rows)+ ('\n' if rows else '')
    width=len(header)
    sep='-'*width
    out=[]
    if 'no-headers' not in flags:out.extend([header,sep])
    out.extend(rows); out.append(sep)
    out.append(f"{len(selected)} todos (of {len(lines)} total)")
    return '\n'.join(out)+'\n'

def main():
    argv=sys.argv[1:]
    if any(x in ('--help','-h') for x in argv):
        print('Usage: ttdl [command] [ID range] [subject] [options]\nCommands: list add done undone remove edit append prepend clean stats listprojects listcontexts listhashtags agenda')
        return 0
    cmd,pos,opts,flags,projects,contexts=parse_args(argv)
    filename=paths(argv)
    if '--done' in flags:
        filename=os.path.join(os.path.dirname(filename),'done.txt');flags.add('only-completed')
    try:
        with open(filename,encoding='utf-8') as f:lines=f.read().splitlines()
    except FileNotFoundError:lines=[]
    if cmd=='add':
        text=' '.join(pos).strip()
        if not text:text=sys.stdin.read().strip()
        if not text:print('Subject is empty');return 1
        with open(filename,'a',encoding='utf-8') as f:
            if lines:f.write('\n')
            f.write(text+'\n')
        print('Added todo:')
        updated=lines+[text]
        print(render(updated,[(len(updated),text)],set(),{}),end='')
        return 0
    if cmd=='stats':print(run_stats(lines,'short' in flags or 'short' in opts));return 0
    if cmd in ('listprojects','listcontexts','listhashtags'):
        kind={'listprojects':'projects','listcontexts':'contexts','listhashtags':'hashtags'}[cmd];print(run_taglist(lines,kind),end='');return 0
    if cmd=='agenda':
        on=opts.get('on') or (pos[0] if pos else None)
        start,end=480,1200
        value=opts.get('time')
