    if not m:return None
    return (int(m[1] or ('-1' if token.startswith('-') else '1')),m[2] or 'd')

def _shift(day,n,unit):
    if unit=='d':return day+dt.timedelta(days=n)
    if unit=='w':return day+dt.timedelta(days=n*7)
    if unit=='m':return _add_months(day,n)
    return _add_months(day,n*12)

def _range(spec,today):
    strict=(spec or '').startswith('+')
    s=(spec or '1m')
    if strict:s=s[1:]
    if '..' in s:
        a,b=s.split('..',1);da=_delta(a);db=_delta(b)
        if da is None or db is None:return None
        start=_shift(today,*da) if a else today
        end=_shift(today,*db) if b else today
        return (min(start,end),max(start,end))
    d=_delta(s)
    if d is None:return None
    n,u=d
    if u in ('w','m','y') and not strict:
        if u=='w':
            base=today-dt.timedelta(days=(today.weekday()+1)%7)
            count=max(1,abs(n))
